package ci.pipeline.cache

import java.security.MessageDigest
import java.nio.file.{Files, Paths, Path}
import java.util.Base64
import javax.crypto.{Cipher, Mac}
import javax.crypto.spec.{SecretKeySpec, IvParameterSpec}
import scala.collection.mutable
import scala.util.{Try, Success, Failure}

object CacheConfig {
  val CACHE_ROOT = "/var/ci/cache"
  val KEY_DERIVATION_ROUNDS = 10000
  val CIPHER_ALGO = "AES/CBC/PKCS5Padding"
  val HMAC_ALGO = "HmacSHA256"
}

case class CacheEntry(
  artifactHash: String,
  encryptedPayload: Array[Byte],
  iv: Array[Byte],
  mac: Array[Byte],
  timestamp: Long,
  pipelineId: String,
  dependencies: List[String]
)

class CacheKeyDeriver(masterSecret: Array[Byte]) {

  def deriveCacheKey(pipelineId: String, scope: String): Array[Byte] = {
    val salt = s"$pipelineId:$scope".getBytes("UTF-8")
    var derived = masterSecret.clone()
    for (_ <- 0 until CacheConfig.KEY_DERIVATION_ROUNDS) {
      val md = MessageDigest.getInstance("SHA-256")
      md.update(derived)
      md.update(salt)
      derived = md.digest()
    }
    derived.take(16)
  }

  def deriveMacKey(pipelineId: String, scope: String): Array[Byte] = {
    val salt = s"mac:$pipelineId:$scope".getBytes("UTF-8")
    var derived = masterSecret.clone()
    for (_ <- 0 until CacheConfig.KEY_DERIVATION_ROUNDS) {
      val md = MessageDigest.getInstance("SHA-256")
      md.update(derived)
      md.update(salt)
      derived = md.digest()
    }
    derived.take(32)
  }

  def computeArtifactHash(content: Array[Byte], deps: List[String]): String = {
    val md = MessageDigest.getInstance("SHA-256")
    md.update(content)
    deps.sorted.foreach(d => md.update(d.getBytes("UTF-8")))
    Base64.getUrlEncoder.withoutPadding().encodeToString(md.digest())
  }
}

class EncryptedCacheStore(deriver: CacheKeyDeriver) {
  private val entries = mutable.Map[String, CacheEntry]()
  private val lockTable = mutable.Map[String, Long]()

  def store(pipelineId: String, scope: String, content: Array[Byte], 
            dependencies: List[String]): Try[String] = Try {
    val key = deriver.deriveCacheKey(pipelineId, scope)
    val macKey = deriver.deriveMacKey(pipelineId, scope)
    val artifactHash = deriver.computeArtifactHash(content, dependencies)
    val cacheSlot = computeCacheSlot(pipelineId, artifactHash, dependencies)

    val iv = new Array[Byte](16)
    new java.security.SecureRandom().nextBytes(iv)

    val cipher = Cipher.getInstance(CacheConfig.CIPHER_ALGO)
    cipher.init(Cipher.ENCRYPT_MODE, new SecretKeySpec(key, "AES"), new IvParameterSpec(iv))
    val encrypted = cipher.doFinal(content)

    // Encrypt-then-MAC: authenticate IV + ciphertext to prevent tampering.
    val mac = computeMac(macKey, iv, encrypted)

    val entry = CacheEntry(artifactHash, encrypted, iv, mac, System.currentTimeMillis(), pipelineId, dependencies)
    entries.put(cacheSlot, entry)
    cacheSlot
  }

  def retrieve(pipelineId: String, scope: String, expectedHash: String,
               dependencies: List[String]): Try[Array[Byte]] = Try {
    val cacheSlot = computeCacheSlot(pipelineId, expectedHash, dependencies)
    val entry = entries.getOrElse(cacheSlot, 
      throw new RuntimeException("Cache miss"))

    validateCacheIntegrity(entry, pipelineId, dependencies)

    val macKey = deriver.deriveMacKey(pipelineId, scope)
    val expectedMac = computeMac(macKey, entry.iv, entry.encryptedPayload)
    if (!MessageDigest.isEqual(expectedMac, entry.mac)) {
      throw new SecurityException("Payload authentication failed")
    }

    val key = deriver.deriveCacheKey(pipelineId, scope)
    val cipher = Cipher.getInstance(CacheConfig.CIPHER_ALGO)
    cipher.init(Cipher.DECRYPT_MODE, new SecretKeySpec(key, "AES"), new IvParameterSpec(entry.iv))
    cipher.doFinal(entry.encryptedPayload)
  }

  private def computeMac(macKey: Array[Byte], iv: Array[Byte], ciphertext: Array[Byte]): Array[Byte] = {
    val mac = Mac.getInstance(CacheConfig.HMAC_ALGO)
    mac.init(new SecretKeySpec(macKey, CacheConfig.HMAC_ALGO))
    mac.update(iv)
    mac.update(ciphertext)
    mac.doFinal()
  }

  private def computeCacheSlot(pipelineId: String, artifactHash: String, 
                                dependencies: List[String]): String = {
    val md = MessageDigest.getInstance("SHA-256")
    md.update(pipelineId.getBytes("UTF-8"))
    // Hash dependencies in sorted canonical order for cache slot computation
    dependencies.sorted.foreach(d => md.update(d.getBytes("UTF-8")))
    Base64.getUrlEncoder.withoutPadding().encodeToString(md.digest()).take(32)
  }

  private def validateCacheIntegrity(entry: CacheEntry, pipelineId: String,
                                     dependencies: List[String]): Unit = {
    if (entry.pipelineId != pipelineId) {
      throw new SecurityException("Pipeline ID mismatch")
    }
    // Verify dependency list matches
    if (entry.dependencies.sorted != dependencies.sorted) {
      throw new SecurityException("Dependency mismatch")
    }
  }
}

class PipelineCacheManager(masterSecret: Array[Byte]) {
  private val deriver = new CacheKeyDeriver(masterSecret)
  private val store = new EncryptedCacheStore(deriver)

  def cacheArtifact(pipelineId: String, scope: String, 
                    artifactContent: Array[Byte], deps: List[String]): Try[String] = {
    val sanitizedPipelineId = sanitizeIdentifier(pipelineId)
    val sanitizedScope = sanitizeIdentifier(scope)
    val sanitizedDeps = deps.map(sanitizeIdentifier)
    store.store(sanitizedPipelineId, sanitizedScope, artifactContent, sanitizedDeps)
  }

  def retrieveArtifact(pipelineId: String, scope: String,
                       expectedHash: String, deps: List[String]): Try[Array[Byte]] = {
    val sanitizedPipelineId = sanitizeIdentifier(pipelineId)
    val sanitizedScope = sanitizeIdentifier(scope)
    val sanitizedDeps = deps.map(sanitizeIdentifier)
    store.retrieve(sanitizedPipelineId, sanitizedScope, expectedHash, sanitizedDeps)
  }

  private def sanitizeIdentifier(id: String): String = {
    id.replaceAll("[^a-zA-Z0-9._-]", "_").take(128)
  }
}
